    "question": "Concernant les veines du membre supérieur, cochez la ou les proposition(s) exacte(s) :",
    "propositions": {
      "A": "Les veines profondes sont utilisées pour les prélèvements sanguins usuels.",
      "B": "La veine basilique se draine directement dans la veine axillaire.",
      "C": "La veine latérale du pouce est appelée veine céphalique du pouce.",
      "D": "L'artère axillaire est accompagnée de deux veines axillaires.",
      "E": "Les veines profondes ont les mêmes rapports que les artères homologues."
    },
    "question_fr": "Concernant les veines du membre supérieur, cochez la ou les proposition(s) exacte(s) :",
