      "A": "L'anatomie descriptive est l'étude analytique de la morphologie des organes.",
      "B": "Un organe correspond à un ensemble de cellules ayant la même différenciation fonctionnelle.",
      "C": "Les fonctions de nutrition sont accomplies par l'appareil reproducteur.",
