    "question": "Concernant les généralités en neurologie, cochez la ou les proposition(s) exacte(s) :",
    "propositions": {
      "A": "L'encéphale correspond à la partie intracrânienne du système nerveux central.",
      "B": "Le neurone est l'unité fonctionnelle du système nerveux.",
      "C": "La substance grise est périphérique et superficielle dans la moelle épinière.",
      "D": "Le système nerveux périphérique est constitué des nerfs crâniens et spinaux.",
      "E": "Le système nerveux somatique est divisé en systèmes sympathique et parasympathique."
    },
