      "B": "Le faisceau antéro-médial provient de la branche ventrale du tronc primaire inférieur.",
      "C": "Le faisceau postérieur se divise en nerf axillaire et nerf radial.",
      "D": "Le tronc primaire intermédiaire du plexus brachial est constitué par les troncs secondaires.",
