    "question_fr": "Concernant le plexus brachial :",
    "question_en": "Concerning the brachial plexus:",
    "propositions_fr": {
      "A": "Le tronc supérieur est formé par la réunion des rameaux ventraux de C5 et C6.",
      "B": "Le faisceau antéro-médial provient de la branche ventrale du tronc primaire inférieur.",
      "C": "Le faisceau postérieur se divise en nerf axillaire et nerf radial.",
      "D": "Le tronc primaire intermédiaire du plexus brachial est constitué par les troncs secondaires.",
      "E": "Ses branches collatérales sont purement sensitives."
    },
    "propositions_en": {
      "A": "The superior trunk is formed by the union of the ventral rami of C5 and C6.",
      "B": "The anteromedial cord originates from the ventral branch of the inferior primary trunk.",
      "C": "The posterior cord divides into the axillary nerve and the radial nerve.",
      "D": "The intermediate primary trunk of the brachial plexus is constituted by the secondary trunks.",
      "E": "Its collateral branches are purely sensory."
    },
