    "question": "Concernant les articulations, cochez la (les) proposition(s) exacte(s) :",
    "propositions": {
      "A": "La syndesmose est une articulation fibreuse où le tissu fibreux s'ossifie avec l'âge.",
      "B": "Les articulations diaphysaires-épiphysaires sont des synchondroses.",
      "C": "Le labrum est un disque intra-articulaire adhérant à la capsule par son bord périphérique.",
      "D": "Dans une énarthrose (sphéroïde), les surfaces articulaires sont des segments de poulie, l'un convexe, l'autre concave.",
      "E": "Un ginglyme (trochléenne) est une articulation à deux axes et deux plans de mouvement."
    },
    "question_fr": "Concernant les articulations, cochez la (les) proposition(s) exacte(s) :",
    "question_en": "Concerning joints, Check the correct proposition(s):",
    "propositions_fr": {
      "A": "La syndesmose est une articulation fibreuse où le tissu fibreux s'ossifie avec l'âge.",
      "B": "Les articulations diaphysaires-épiphysaires sont des synchondroses.",
      "C": "Le labrum est un disque intra-articulaire adhérant à la capsule par son bord périphérique.",
      "D": "Dans une énarthrose (sphéroïde), les surfaces articulaires sont des segments de poulie, l'un convexe, l'autre concave.",
      "E": "Un ginglyme (trochléenne) est une articulation à deux axes et deux plans de mouvement."
    },
    "propositions_en": {
      "A": "Syndesmosis is a fibrous joint where the fibrous tissue ossifies with age.",
      "B": "Diaphyseal-epiphyseal joints are synchondroses.",
      "C": "The labrum is an intra-articular disc adhering to the capsule by its peripheral border.",
      "D": "In an enarthrosis (ball and socket), the articular surfaces are segments of a pulley, one convex, the other concave.",
      "E": "A ginglymus (hinge) joint is a joint with two axes and two planes of movement."
    },
    "bonnes_reponses": [
      "B"
    ],
