    "question": "Concernant la scapula, cochez la (les) proposition(s) exacte(s) :",
    "propositions": {
      "A": "L'acromion est un prolongement du processus coracoïde.",
      "B": "L'incisure scapulaire se situe au niveau du bord axillaire.",
      "C": "Le tubercule supra-glénoïdal donne insertion au chef long du muscle biceps brachial.",
      "D": "Le tubercule infra-glénoïdal donne insertion au chef court du biceps brachial.",
      "E": "Le muscle petit pectoral s'attache sur le processus coracoïde."
    },
    "question_fr": "Concernant la scapula, cochez la (les) proposition(s) exacte(s) :",
    "question_en": "Concerning the scapula, check the correct proposition(s):",
