    "question": "Concernant l'humérus, cochez la (les) proposition(s) exacte(s) :",
    "propositions": {
      "A": "La tubérosité deltoïdienne se situe sur sa face antéro-latérale.",
      "B": "Le col chirurgical sépare la tête humérale des grand et petit tubercules.",
      "C": "L'angle d'inclinaison de la tête humérale est de 140°.",
      "D": "Le muscle infra-épineux s'attache sur la facette moyenne du grand tubercule.",
      "E": "Le sillon intertuberculaire livre passage au chef court du biceps brachial."
    },
    "question_fr": "Concernant l'humérus, cochez la (les) proposition(s) exacte(s) :",
    "question_en": "Concerning the humerus, check the correct proposition(s):",
    "propositions_fr": {
      "A": "La tubérosité deltoïdienne se situe sur sa face antéro-latérale.",
      "B": "Le col chirurgical sépare la tête humérale des grand et petit tubercules.",
      "C": "L'angle d'inclinaison de la tête humérale est de 140°.",
      "D": "Le muscle infra-épineux s'attache sur la facette moyenne du grand tubercule.",
      "E": "Le sillon intertuberculaire livre passage au chef court du biceps brachial."
    },
    "propositions_en": {
      "A": "The deltoid tuberosity is on its anterolateral surface.",
      "B": "The surgical neck separates the head from the greater and lesser tubercles.",
      "C": "The angle of inclination of the humeral head is 140°.",
      "D": "The infraspinatus muscle attaches to the middle facet of the greater tubercle.",
      "E": "The intertubercular sulcus transmits the short head of the biceps brachii."
    },
