    "question": "Concernant les muscles de l'avant-bras, cochez la (les) proposition(s) exacte(s) :",
    "propositions": {
      "A": "Les muscles de l'avant-bras sont divisés en loges antérieure et postérieure.",
      "B": "Le muscle rond pronateur possède deux chefs : radial et ulnaire.",
      "C": "Le plan moyen de la loge antérieure est formé par le muscle fléchisseur superficiel des doigts.",
      "D": "Le muscle long palmaire est un extenseur de la main sur l'avant-bras.",
      "E": "Le fléchisseur profond des doigts s'insère sur la base des phalanges moyennes des 4 doigts."
    },
    "question_fr": "Concernant les muscles de l'avant-bras, cochez la (les) proposition(s) exacte(s) :",
    "question_en": "Concerning the muscles of the forearm, check the correct proposition(s):",
    "propositions_fr": {
      "A": "Les muscles de l'avant-bras sont divisés en loges antérieure et postérieure.",
      "B": "Le muscle rond pronateur possède deux chefs : radial et ulnaire.",
      "C": "Le plan moyen de la loge antérieure est formé par le muscle fléchisseur superficiel des doigts.",
      "D": "Le muscle long palmaire est un extenseur de la main sur l'avant-bras.",
      "E": "Le fléchisseur profond des doigts s'insère sur la base des phalanges moyennes des 4 doigts."
    },
    "propositions_en": {
      "A": "The muscles of the forearm are divided into anterior and posterior compartments.",
      "B": "The pronator teres muscle has two heads: radial and ulnar.",
      "C": "The middle plane of the anterior compartment is formed by the flexor digitorum superficialis muscle.",
      "D": "The palmaris longus muscle is an extensor of the hand on the forearm.",
      "E": "The flexor digitorum profundus inserts on the base of the middle phalanges of the 4 fingers."
    },
    "bonnes_reponses": [
      "A",
      "C"
    ],
